css:
/* Two Models, One Firm — Corporate / Executive Boardroom theme (deep navy + brass) */
.brightwell-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #0c1626 0%, #14233b 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #dce4ef;
}

/* ---- Header ---- */
.brightwell-sim-container .bw-header {
    background: linear-gradient(135deg, #0a1320 0%, #1c2f4d 100%);
    border: 1px solid #25395c;
    padding: 30px 34px;
    border-radius: 16px;
    margin-bottom: 22px;
    position: relative;
    overflow: hidden;
    box-shadow: 0 14px 36px rgba(0,0,0,0.45);
}
.brightwell-sim-container .bw-header::after {
    content: '';
    position: absolute;
    right: -50px;
    top: -50px;
    width: 220px;
    height: 220px;
    background: radial-gradient(circle at center, #c9a227 0%, transparent 70%);
    opacity: 0.22;
}
.brightwell-sim-container .bw-eyebrow {
    text-transform: uppercase;
    letter-spacing: 0.2em;
    font-size: 0.7rem;
    color: #d4b24c;
    margin-bottom: 8px;
    font-weight: 600;
}
.brightwell-sim-container .bw-header h1 {
    margin: 0 0 6px 0;
    font-size: 2.2rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: #f4f7fc;
}
.brightwell-sim-container .bw-subtitle {
    margin: 0 0 18px 0;
    color: #9fb2cc;
    font-size: 1rem;
    max-width: 760px;
    line-height: 1.5;
}
.brightwell-sim-container .bw-period-strip {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(201,162,39,0.12);
    border: 1px solid #c9a227;
    border-radius: 999px;
    padding: 8px 18px;
    font-weight: 600;
    font-size: 0.92rem;
    color: #e9d99a;
}
.brightwell-sim-container .bw-period-strip #currentDay,
.brightwell-sim-container .bw-period-strip #maxPeriods {
    color: #f4d976;
    font-size: 1.25rem;
    font-weight: 700;
}

/* ---- Scorecard ---- */
.brightwell-sim-container .bw-scorecard {
    display: grid;
    grid-template-columns: 1.4fr repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 22px;
}
.brightwell-sim-container .bw-kpi {
    background: #16263f;
    border: 1px solid #24395d;
    border-radius: 14px;
    padding: 16px 18px;
    border-top: 3px solid #3b5a86;
}
.brightwell-sim-container .bw-kpi-hero {
    border-top: 3px solid #c9a227;
    background: linear-gradient(160deg, #1a2c49 0%, #142339 100%);
}
.brightwell-sim-container .bw-kpi-label {
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-size: 0.66rem;
    color: #8aa0c0;
    margin-bottom: 8px;
    font-weight: 600;
}
.brightwell-sim-container .bw-kpi-value {
    font-size: 1.55rem;
    font-weight: 700;
    color: #f4f7fc;
    line-height: 1.1;
}
.brightwell-sim-container .bw-kpi-hero .bw-kpi-value {
    font-size: 2.6rem;
    color: #f4d976;
}
.brightwell-sim-container .bw-kpi-sub {
    font-size: 0.72rem;
    color: #6f87a8;
    margin-top: 6px;
}
.brightwell-sim-container .bw-kpi-value.is-good { color: #5fd6a0; }
.brightwell-sim-container .bw-kpi-value.is-warn { color: #f0c24b; }
.brightwell-sim-container .bw-kpi-value.is-bad  { color: #f08a8a; }

/* ---- Briefing ---- */
.brightwell-sim-container .bw-briefing {
    background: #11203a;
    border: 1px solid #2a4068;
    border-left: 4px solid #c9a227;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 22px;
}
.brightwell-sim-container .bw-briefing-tag {
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.68rem;
    color: #d4b24c;
    margin-bottom: 8px;
    font-weight: 700;
}
.brightwell-sim-container .bw-briefing-text {
    color: #cdd9ec;
    font-size: 1rem;
    line-height: 1.65;
}
.brightwell-sim-container .bw-briefing-text strong { color: #f4f7fc; }

/* ---- Controls ---- */
.brightwell-sim-container .bw-controls {
    background: #14233b;
    border: 1px solid #24395d;
    border-radius: 16px;
    padding: 26px 28px;
    margin-bottom: 22px;
    box-shadow: 0 6px 22px rgba(0,0,0,0.3);
}
.brightwell-sim-container .bw-controls h3 {
    margin: 0 0 18px 0;
    font-size: 1.15rem;
    color: #f4f7fc;
    border-bottom: 2px solid #c9a227;
    padding-bottom: 8px;
    display: inline-block;
}
.brightwell-sim-container .bw-field {
    margin-bottom: 22px;
    padding-bottom: 20px;
    border-bottom: 1px dashed #243a5c;
}
.brightwell-sim-container .bw-field:last-of-type { border-bottom: none; }
.brightwell-sim-container .bw-field > label,
.brightwell-sim-container .bw-sub-field > label {
    display: block;
    font-size: 0.9rem;
    font-weight: 600;
    color: #e3ebf6;
    margin-bottom: 8px;
}
.brightwell-sim-container .bw-subhead {
    margin-top: 6px;
    color: #b9c8de !important;
}
.brightwell-sim-container .bw-help {
    margin: 8px 0 0 0;
    font-size: 0.82rem;
    color: #8aa0c0;
    font-style: italic;
    line-height: 1.45;
}

.brightwell-sim-container input[type="number"],
.brightwell-sim-container select {
    width: 100%;
    background: #0d1a2e;
    color: #f4f7fc;
    border: 1px solid #2f4870;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.brightwell-sim-container input[type="number"]:focus,
.brightwell-sim-container select:focus {
    outline: none;
    border-color: #c9a227;
    box-shadow: 0 0 0 3px rgba(201,162,39,0.18);
}
.brightwell-sim-container select option {
    background-color: #0d1a2e;
    color: #f4f7fc;
}

/* ---- Range sliders ---- */
.brightwell-sim-container .bw-range-wrap {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.brightwell-sim-container input[type="range"] {
    width: 100%;
    accent-color: #c9a227;
    height: 6px;
    cursor: pointer;
}
.brightwell-sim-container .bw-range-ends {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.74rem;
    color: #8aa0c0;
}
.brightwell-sim-container .bw-range-readout {
    background: #c9a227;
    color: #14233b;
    font-weight: 700;
    border-radius: 6px;
    padding: 2px 10px;
    font-size: 0.85rem;
    align-self: center;
}

/* ---- Toggles ---- */
.brightwell-sim-container .bw-toggles {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    background: #0f1d33;
    padding: 14px 16px;
    border-radius: 10px;
    margin-top: 8px;
}
.brightwell-sim-container .bw-toggle {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.86rem;
    color: #cdd9ec;
    margin: 0;
    cursor: pointer;
}
.brightwell-sim-container .bw-toggle input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #c9a227;
    cursor: pointer;
    flex-shrink: 0;
}
.brightwell-sim-container .bw-broker-deal {
    margin-top: 14px;
    background: #0f1d33;
    padding: 12px 14px;
    border-radius: 8px;
}

/* ---- Sub grids ---- */
.brightwell-sim-container .bw-grid-3 {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}
.brightwell-sim-container .bw-sub-field { margin-bottom: 4px; }

/* ---- Actions ---- */
.brightwell-sim-container .bw-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 10px;
}
.brightwell-sim-container .bw-actions .btn-primary {
    background: #c9a227;
    border-color: #c9a227;
    color: #14233b;
    padding: 11px 26px;
    font-weight: 700;
    border-radius: 8px;
    transition: background 0.2s ease, transform 0.1s ease;
}
.brightwell-sim-container .bw-actions .btn-primary:hover {
    background: #e0b842;
    transform: translateY(-1px);
}
.brightwell-sim-container .bw-actions .btn-outline-secondary {
    color: #9fb2cc;
    border-color: #2f4870;
    border-radius: 8px;
}
.brightwell-sim-container .bw-actions .btn-outline-secondary:hover {
    color: #f4f7fc;
    border-color: #c9a227;
    background: transparent;
}

/* ---- Feedback ---- */
.brightwell-sim-container .bw-feedback {
    background: #0a1320;
    border: 1px solid #2a4068;
    border-left: 5px solid #c9a227;
    border-radius: 12px;
    padding: 22px 26px;
    margin-bottom: 22px;
    display: none;
}
.brightwell-sim-container .bw-feedback.is-visible { display: block; }
.brightwell-sim-container .bw-feedback-tag {
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.68rem;
    color: #d4b24c;
    margin-bottom: 12px;
    font-weight: 700;
}
.brightwell-sim-container .bw-feedback-text {
    line-height: 1.7;
    font-size: 0.97rem;
    color: #cdd9ec;
}
.brightwell-sim-container .bw-feedback-text .pos { color: #6fe0aa; }
.brightwell-sim-container .bw-feedback-text .neg { color: #f29a9a; }
.brightwell-sim-container .bw-feedback-text .warn { color: #f0c24b; }

/* ---- History ---- */
.brightwell-sim-container .bw-history {
    background: #14233b;
    border: 1px solid #24395d;
    border-radius: 14px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.brightwell-sim-container .bw-history h3 {
    margin: 0 0 14px 0;
    font-size: 1.05rem;
    color: #f4f7fc;
}
.brightwell-sim-container .bw-history table {
    margin: 0;
    color: #cdd9ec;
}
.brightwell-sim-container .bw-history th {
    background: #0f1d33;
    color: #b9c8de;
    font-weight: 600;
    font-size: 0.82rem;
    border-color: #24395d;
}
.brightwell-sim-container .bw-history td {
    border-color: #1d3050;
    font-size: 0.86rem;
}

/* ---- Chart ---- */
.brightwell-sim-container .bw-chart {
    background: #14233b;
    border: 1px solid #24395d;
    border-radius: 14px;
    padding: 22px;
    height: 360px;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .brightwell-sim-container { padding: 16px; }
    .brightwell-sim-container .bw-scorecard { grid-template-columns: 1fr 1fr; }
    .brightwell-sim-container .bw-kpi-hero { grid-column: 1 / -1; }
    .brightwell-sim-container .bw-grid-3 { grid-template-columns: 1fr; }
    .brightwell-sim-container .bw-toggles { grid-template-columns: 1fr; }
    .brightwell-sim-container .bw-header h1 { font-size: 1.6rem; }
    .brightwell-sim-container .bw-kpi-hero .bw-kpi-value { font-size: 2rem; }
    .brightwell-sim-container .bw-chart { height: 300px; }
}


/* FIX v1.1.0 — completion / board-verdict screen */
.bw-completion { padding: 10px 6px; text-align: center; }
.bw-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.bw-completion-verdict { font-size: 22px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.bw-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.bw-completion-score strong { color: #1d4ed8; }
.bw-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.bw-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 100px; }
.bw-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.bw-completion-metric strong { font-size: 16px; color: #0f172a; }
.bw-completion-note { max-width: 680px; margin: 0 auto; text-align: left; padding: 12px 16px; background: #f8fafc; border-left: 3px solid #1d4ed8; border-radius: 4px; color: #1e293b; font-size: 14px; line-height: 1.5; }

