                    coreRatio: this.CORE_RATIO_START,   // % combined ratio of the core
                    coreBook: 2100000,                  // policyholders
                    futureBookHealth: 100,              // index 0-100, under-35 pipeline
                    // New model
                    newModelBook: 0,                    // direct-digital customers
                    venturePaidIn: 0,                   // £M build capital deployed cumulatively
                    structureSet: false,                // separation/shared-assets locked in
                    separation: 50,
                    // Tensions
                    conflictIndex: 0,                   // 0-100 org + channel conflict
                    brokerGoodwill: 100,                // 0-100; brokers write 88% of premium
                    cumCannibalized: 0,                 // direct wins taken from own brokers
                    // Outcomes
                    combinedRatio: this.CORE_RATIO_START,
                    combinedResult: 72,                 // £M underwriting result (6pts of 1200)
                    breaches: 0,
                    // History for charts
                    profitHistory: [],
                    ratioHistory: [],
                    newModelHistory: [],
                    conflictHistory: [],
                    cannibHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    secondModel: 'no',
                    separation: 50,
                    shareData: true,
                    shareCapital: true,
                    shareBrand: false,
                    shareOps: false,
                    capital: 12,
                    talent: 40,
                    attention: 30,
                    cannibTolerance: 40,
                    recovery: 'ringfence',
                    brokerDeal: false
                };
            }
            this._updateBriefing(state);
        }

        // -------------------------------------------------- validate
        validateDecisions(decisions) {
            const g = (id) => document.getElementById(id);
            const sm = g('secondModelSelect');
            const sep = g('separationRange');
            const sData = g('shareData');
            const sCap = g('shareCapital');
            const sBrand = g('shareBrand');
            const sOps = g('shareOps');
            const cap = g('capitalInput');
            const tal = g('talentInput');
            const att = g('attentionRange');
            const ctol = g('cannibToleranceRange');
            const rec = g('recoverySelect');
            const deal = g('brokerDeal');

            if (sm) decisions.secondModel = sm.value;
            if (sep) decisions.separation = parseInt(sep.value, 10);
            if (sData) decisions.shareData = sData.checked;
            if (sCap) decisions.shareCapital = sCap.checked;
            if (sBrand) decisions.shareBrand = sBrand.checked;
            if (sOps) decisions.shareOps = sOps.checked;
            if (cap) decisions.capital = parseFloat(cap.value);
            if (tal) decisions.talent = parseInt(tal.value, 10);
            if (att) decisions.attention = parseInt(att.value, 10);
            if (ctol) decisions.cannibTolerance = parseInt(ctol.value, 10);
            if (rec) decisions.recovery = rec.value;
            if (deal) decisions.brokerDeal = deal.checked;

            const warn = (k) => window.mySimulation.uiManager.showNotification(
                window.mySimulation.t(k), 'warning');

            if (!Number.isFinite(decisions.capital) || decisions.capital < 0 || decisions.capital > this.BUILD_BUDGET) {
                warn('warn_capital');
                return false;
            }
            if (!Number.isFinite(decisions.talent) || decisions.talent < 0 || decisions.talent > 120) {
                warn('warn_talent');
                return false;
            }
            // If you commit to a second model you must put at least some build capital behind it.
            if (decisions.secondModel === 'yes' && decisions.capital < 1) {
                warn('warn_underfund');
                return false;
            }
            return true;
        }

        // -------------------------------------------------- helpers (pure)
        _separationCost(d) {
            // How much of the shared-asset advantage is forfeited by separating.
            // Higher separation + fewer shared assets => more rebuild cost, slower ramp.
            const sepFrac = d.separation / 100;
            let sharedScore = 0;
            if (d.shareData) sharedScore += 0.30;   // 38 years pricing data — most valuable
            if (d.shareCapital) sharedScore += 0.30; // balance sheet funds the build
            if (d.shareOps) sharedScore += 0.25;     // underwriting & claims
            if (d.shareBrand) sharedScore += 0.15;   // brand (also raises cannibalization)
            // sharedScore in [0,1]; 1 = leverages everything.
            return { sepFrac: sepFrac, sharedScore: sharedScore };
        }

        // -------------------------------------------------- calculate
        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const t = window.mySimulation.t.bind(window.mySimulation);
            const period = state.currentPeriod;
            const notes = [];

            const committed = d.secondModel === 'yes';
            const piloting = d.secondModel === 'watch';

            // ===== 1. CORE BOOK DRIFT =====
            // The disruptor erodes the under-35 future book every quarter unless we respond.
            let futureErosion = 6; // baseline quarterly erosion of future-book health
            if (committed) futureErosion = 1.5;
            else if (piloting) futureErosion = 4;
            // Refusing the second model (Markides: strategic paralysis) bleeds the future.
            ds.futureBookHealth = Math.max(0, ds.futureBookHealth - futureErosion);

            // Management attention: too little => core drifts; too much => core also drifts.
            // The core needs the bulk of attention; ideal split leaves ~70% on core.
            let attentionDrift = 0;
            if (committed || piloting) {
                const att = d.attention;
                if (att > 55) {
                    attentionDrift = (att - 55) * 0.025; // chasing the shiny launch, core creeps
                    notes.push('<span class="neg">' + t('note_attention_drift') + '</span>');
                } else if (att < 15 && committed) {
                    attentionDrift = (15 - att) * 0.02; // venture starved of leadership
                    notes.push('<span class="neg">' + t('note_attention_starve') + '</span>');
                } else {
                    notes.push('<span class="pos">' + t('note_attention_ok') + '</span>');
                }
            }
            ds.coreRatio = Math.max(90, ds.coreRatio + attentionDrift);

            // ===== 2. SECOND-MODEL RAMP =====
            let newWins = 0;          // gross direct-digital wins this quarter
            let ventureExpense = 0;   // £M build spend that hits the combined ratio
            let cannibRate = 0;       // % of wins taken from own brokers
            const sc = this._separationCost(d);

            if (committed || piloting) {
                ds.structureSet = true;
                ds.separation = d.separation;
                // Capital deployed cumulatively (cannot exceed the 2-yr budget overall)
                const room = this.BUILD_BUDGET - ds.venturePaidIn;
                const spend = piloting ? Math.min(d.capital, room, 4) : Math.min(d.capital, room);
                ds.venturePaidIn += spend;
                ventureExpense = spend;

                // Talent + capital + shared assets drive the ramp.
                const talentFactor = Math.min(1, d.talent / 80);
                const capitalFactor = piloting ? 0.25 : Math.min(1, ds.venturePaidIn / 30);
                // Shared assets accelerate; over-separation forfeits them (rebuild penalty).
                const assetFactor = 0.35 + 0.65 * sc.sharedScore;
                // Separation dial: a little autonomy is good (speed); zero autonomy = starved.
                let autonomyFactor;
                if (sc.sepFrac < 0.2) autonomyFactor = 0.45;       // strangled inside core P&L
                else if (sc.sepFrac <= 0.7) autonomyFactor = 1.0;  // the sweet spot
                else autonomyFactor = 0.8;                          // fully separate = slower rebuild
                const base = piloting ? 14000 : 52000;
                newWins = Math.round(base * talentFactor * capitalFactor * assetFactor * autonomyFactor);

                // ===== 3. CANNIBALIZATION =====
                // Sharing the brand raises overlap with the broker book; tolerance caps discipline.
                let overlap = 0.55;
                if (d.shareBrand) overlap += 0.20; // same brand confuses channel, pulls own customers
                if (sc.sepFrac > 0.7) overlap -= 0.25; // distinct brand/entity captures NEW market
                overlap = Math.max(0.1, Math.min(0.9, overlap));
                const actualCannibShare = Math.min(overlap, d.cannibTolerance / 100 + 0.05);
                cannibRate = Math.round(actualCannibShare * 100);
                const cannibalized = Math.round(newWins * actualCannibShare);
                ds.cumCannibalized += cannibalized;

                if (cannibRate >= 65) {
                    notes.push('<span class="neg">' + t('note_cannib_high') + '</span>');
                } else if (cannibRate <= 35 && newWins > 0) {
                    notes.push('<span class="pos">' + t('note_cannib_disciplined') + '</span>');
                }

                ds.newModelBook += newWins;
            } else {
                // No second model: concede the segment.
                notes.push('<span class="warn">' + t('note_paralysis') + '</span>');
            }

            // ===== 4. BROKER / CHANNEL CONFLICT =====
            // Brokers write 88% of premium and retaliate if attacked without management.
            let conflictDelta = 0;
            if (committed) {
                conflictDelta += 12;                       // baseline tension from competing
                if (d.shareBrand) conflictDelta += 10;     // same brand = open war on own channel
                if (cannibRate >= 65) conflictDelta += 12; // brokers see their book repriced cheaper
                if (sc.sepFrac >= 0.6) conflictDelta -= 6;  // a separate brand softens the clash
                if (d.brokerDeal) {
                    conflictDelta -= 18;                   // revenue-share buys peace
                    notes.push('<span class="pos">' + t('note_broker_peace') + '</span>');
                }
            } else if (piloting) {
                conflictDelta += 3;
            } else {
                conflictDelta -= 8; // brokers stay calm if we don't compete
            }
            ds.conflictIndex = Math.max(0, Math.min(100, ds.conflictIndex + conflictDelta));
            ds.brokerGoodwill = Math.max(0, Math.min(100, ds.brokerGoodwill - conflictDelta));

            // Broker revolt: lost goodwill redirects core premium to rivals.
            let brokerPremiumLoss = 0; // £M underwriting result lost
            if (ds.brokerGoodwill < 70) {
                brokerPremiumLoss = (70 - ds.brokerGoodwill) * 0.45;
                if (ds.brokerGoodwill < 50) {
                    notes.push('<span class="neg">' + t('note_broker_revolt') + '</span>');
                }
            }

            // ===== 5. ROUND 4 SHOCK & RECOVERY =====
            let shockHit = 0;
            if (period === 4) {
                // The shock: broker retaliation + disruptor cuts price again.
                shockHit = 14; // £M baseline hit
                if (d.recovery === 'accelerate') {
                    // Win the future if structured & funded; reckless if conflict already high.
                    if (committed && ds.brokerGoodwill > 55 && ds.venturePaidIn > 20) {
                        newWins += 18000;
                        ds.newModelBook += 18000;
                        shockHit -= 6;
                        notes.push('<span class="pos">' + t('note_rec_accel_good') + '</span>');
                    } else {
                        ds.conflictIndex = Math.min(100, ds.conflictIndex + 14);
                        shockHit += 10;
                        notes.push('<span class="neg">' + t('note_rec_accel_bad') + '</span>');
                    }
                } else if (d.recovery === 'ringfence') {
                    ds.conflictIndex = Math.max(0, ds.conflictIndex - 10);
                    shockHit -= 4;
                    notes.push('<span class="pos">' + t('note_rec_ring') + '</span>');
                } else if (d.recovery === 'reintegrate') {
                    // Re-integration calms brokers but quietly kills the venture (Markides).
                    ds.conflictIndex = Math.max(0, ds.conflictIndex - 16);
                    ds.newModelBook = Math.round(ds.newModelBook * 0.7);
                    shockHit -= 2;
                    notes.push('<span class="warn">' + t('note_rec_reint') + '</span>');
                }
            }

            // ===== 6. COMBINED RATIO & RESULT =====
            // Core underwriting result = (100 - coreRatio)% of GWP (~£72M at 94%).
            const coreResult = (100 - ds.coreRatio) / 100 * this.GWP;
            // New-model contribution: thin/negative while building; brand-share deal costs margin.
            const newModelMargin = (committed && ds.newModelBook > 60000)
                ? (ds.newModelBook - 60000) / 1000 * 0.08 : 0; // small positive once scaled
            const dealCost = d.brokerDeal ? ds.newModelBook / 1000 * 0.12 : 0;
            // Cannibalized customers = value transfer downhill (thinner margin on moved book).
            const cannibDrag = ds.cumCannibalized / 1000 * 0.10;

            const result = coreResult
                + newModelMargin
                - ventureExpense
                - brokerPremiumLoss
                - dealCost
                - cannibDrag
                - shockHit;

            ds.combinedResult = Math.round(result * 10) / 10;
            // Combined ratio: 100 - result/GWP*100 (build spend & losses push it up).
            ds.combinedRatio = Math.round((100 - (ds.combinedResult / this.GWP * 100)) * 10) / 10;

            // ===== 7. MARGIN CEILING CHECK =====
            let breach = false;
            if (ds.combinedRatio > this.RATIO_CEILING) {
                breach = true;
                ds.breaches += 1;
                notes.push('<span class="neg">' + t('note_breach') + '</span>');
            } else if (ds.combinedRatio > this.RATIO_CEILING - 1) {
                notes.push('<span class="warn">' + t('note_near_ceiling') + '</span>');
            } else {
                notes.push('<span class="pos">' + t('note_margin_ok') + '</span>');
            }

            // Future-book warning
            if (ds.futureBookHealth < 40) {
                notes.push('<span class="neg">' + t('note_future_lost') + '</span>');
            }

            // ===== Push history =====
            ds.profitHistory.push(ds.combinedResult);
            ds.ratioHistory.push(ds.combinedRatio);
            ds.newModelHistory.push(ds.newModelBook);
            ds.conflictHistory.push(ds.conflictIndex);
            ds.cannibHistory.push(cannibRate);

            // Render board reaction
            const fbPanel = document.getElementById('boardFeedbackPanel');
            const fbBody = document.getElementById('boardFeedback');
            if (fbPanel && fbBody) {
                fbBody.innerHTML = notes.join('<br>');
                fbPanel.classList.add('is-visible');
            }

            // Next-quarter briefing
            const self = this;
            setTimeout(function () {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // v1.1.0 FIX A — surface a numeric score + grade on the reporting-layer paths
            // (express_resolveDomainScore reads performance.overallScore / domainState.score;
            // trend chart reads results.score/overallScore). Grade thresholds unchanged.
            ds._everCommitted = ds._everCommitted || committed;
            ds._worstRatio = (ds._worstRatio === undefined) ? ds.combinedRatio : Math.max(ds._worstRatio, ds.combinedRatio);
            var _rg = 'paralysis';
            if (ds._everCommitted && ds._worstRatio <= 97 && ds.newModelBook >= 60000 && ds.conflictIndex < 55) _rg = 'ambidextrous';
            else if (ds._everCommitted && ds._worstRatio <= 97 && ds.newModelBook >= 30000) _rg = 'building';
            else if (ds._everCommitted && ds._worstRatio > 97) _rg = 'overreach';
            else if (ds._everCommitted) _rg = 'fragile';
            var _sc = this._gradeScore(_rg);
            ds.score = _sc;
            ds.performance = { overallScore: _sc, grade: t('grade_' + _rg) };
            return {
                period: period,
                score: _sc,
                overallScore: _sc,
                grade: _rg,
                combinedResult: ds.combinedResult,
                combinedRatio: ds.combinedRatio,
                newModelBook: ds.newModelBook,
                cannibRate: cannibRate,
                conflictIndex: ds.conflictIndex,
                breach: breach,
                secondModel: d.secondModel
            };
        }

        // -------------------------------------------------- setupUI
        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');

            uiManager.bind('profitDisplay', 'domainState.combinedResult',
                (v) => (v == null ? '—' : '£' + (Math.round(v * 10) / 10).toFixed(1) + 'M'));
            uiManager.bind('ratioDisplay', 'domainState.combinedRatio',
                (v) => (v == null ? '94.0%' : (Math.round(v * 10) / 10).toFixed(1) + '%'));
            uiManager.bind('cannibDisplay', 'results.cannibRate',
                (v) => (v == null ? '0%' : v + '%'));
            uiManager.bind('newModelDisplay', 'domainState.newModelBook',
                (v) => (!v ? '0' : Number(v).toLocaleString('en-GB')));
            uiManager.bind('conflictDisplay', 'domainState.conflictIndex',
                (v) => (v == null ? '0' : Math.round(v).toString()));

            // Live range read-outs
            const wire = (rangeId, readoutId, suffix) => {
                const r = document.getElementById(rangeId);
                const out = document.getElementById(readoutId);
                if (r && out) {
                    const upd = () => { out.textContent = r.value + (suffix || ''); };
                    r.addEventListener('input', upd);
                    upd();
                }
            };
            wire('separationRange', 'separationReadout', '');
            wire('attentionRange', 'attentionReadout', '%');
            wire('cannibToleranceRange', 'cannibToleranceReadout', '%');
        }

        // -------------------------------------------------- chart
        getChartConfig() {
            return {
                brightwellChart: {
                    type: 'bar',
                    data: { labels: [], datasets: [
                        {
                            label: 'Combined Result (£M)',
                            data: [],
                            backgroundColor: 'rgba(201,162,39,0.75)',
                            borderColor: '#c9a227',
                            borderWidth: 1,
                            yAxisID: 'y',
                            order: 3
                        },
                        {
                            type: 'line',
                            label: 'Combined Ratio (%)',
                            data: [],
                            borderColor: '#f08a8a',
                            backgroundColor: 'rgba(240,138,138,0.12)',
                            borderWidth: 3,
                            tension: 0.25,
                            yAxisID: 'y1',
                            order: 1
                        },
                        {
                            type: 'line',
                            label: 'Org-Conflict Index',
                            data: [],
                            borderColor: '#5f9ed6',
                            backgroundColor: 'rgba(95,158,214,0.1)',
                            borderWidth: 2,
                            borderDash: [5, 4],
                            tension: 0.25,
                            yAxisID: 'y1',
