                            legend: { position: 'bottom', labels: { color: '#9fb2cc' } }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                title: { display: true, text: '£M', color: '#9fb2cc' },
                                ticks: { color: '#8aa0c0' },
                                grid: { color: 'rgba(255,255,255,0.06)' }
                            },
                            y1: {
                                position: 'right',
                                min: 0,
