        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.profitHistory.map((_, i) => 'Q' + (i + 1));
            return {
                brightwellChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.profitHistory },
                        { data: ds.ratioHistory },
                        { data: ds.conflictHistory }
                    ]
                }
            };
        }

        // -------------------------------------------------- end summary
        _gradeScore(grade) {
            var map = { ambidextrous: 90, building: 72, overreach: 52, fragile: 42, paralysis: 22 };
            return (map[grade] != null) ? map[grade] : 0;
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var grade = summary.grade || 'paralysis';
            var score = (summary.score != null) ? summary.score : this._gradeScore(grade);
            var metric = function (label, val) {
                return '<div class="bw-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var pounds = function (v) { return '\u00a3' + Math.round(v || 0) + 'M'; };
            var metrics = ''
                + metric(t('comp_result_label'), pounds(summary.finalResult))
                + metric(t('comp_ratio_label'), (summary.worstRatio != null ? summary.worstRatio : '-') + '%')
                + metric(t('comp_book_label'), Math.round(summary.newModelBook || 0).toLocaleString())
                + metric(t('comp_conflict_label'), (summary.conflictIndex != null ? Math.round(summary.conflictIndex) : '-'));
            return ''
                + '<div class="bw-completion">'
                +   '<div class="bw-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="bw-completion-verdict">' + t('grade_' + grade) + '</div>'
                +   '<div class="bw-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="bw-completion-metrics">' + metrics + '</div>'
                +   '<div class="bw-completion-note">' + t('comp_verdict_' + grade) + '</div>'
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const last = history[history.length - 1].results || {};
            const ratios = history.map(r => (r.results && r.results.combinedRatio) || 100);
            const worstRatio = Math.max.apply(null, ratios);
            const finalResult = last.combinedResult || 0;
            const finalBook = last.newModelBook || 0;
            const finalConflict = last.conflictIndex || 0;
            const everCommitted = history.some(r => r.results && r.results.secondModel === 'yes');

            let grade = 'paralysis';
            if (everCommitted && worstRatio <= 97 && finalBook >= 60000 && finalConflict < 55) {
                grade = 'ambidextrous';
            } else if (everCommitted && worstRatio <= 97 && finalBook >= 30000) {
                grade = 'building';
            } else if (everCommitted && worstRatio > 97) {
                grade = 'overreach';
            } else if (everCommitted) {
                grade = 'fragile';
            }

            return {
                finalResult: finalResult,
                worstRatio: worstRatio,
                newModelBook: finalBook,
                conflictIndex: finalConflict,
                grade: grade,
                score: this._gradeScore(grade)
            };
        }

        // -------------------------------------------------- hint
        getHint(state, results) {
            const t = window.mySimulation.t.bind(window.mySimulation);
            const ds = state.domainState;
            const d = state.decisions;
            if (!results) return null;
            if (d.secondModel === 'no' && ds.futureBookHealth < 70) return t('hint_paralysis');
            if (results.combinedRatio > 97) return t('hint_breach');
            if (d.secondModel === 'yes' && d.separation < 20) return t('hint_starved');
            if (d.secondModel === 'yes' && d.separation > 70 && !d.shareData) return t('hint_overseparate');
            if (results.cannibRate >= 65) return t('hint_cannib');
            if (ds.brokerGoodwill < 60) return t('hint_broker');
            if (d.secondModel === 'yes' && d.attention > 55) return t('hint_attention');
            return t('hint_balanced');
        }

        // -------------------------------------------------- history table
        getHistoryTableConfig() {
            return [
                { key: 'results.combinedResult', label: 'Result', i18nKey: 'col_result',
                  formatter: (v) => '£' + (Math.round(v * 10) / 10).toFixed(1) + 'M' },
                { key: 'results.combinedRatio', label: 'Ratio', i18nKey: 'col_ratio',
                  formatter: (v) => (Math.round(v * 10) / 10).toFixed(1) + '%' },
                { key: 'results.newModelBook', label: 'Direct book', i18nKey: 'col_book',
                  formatter: (v) => Number(v).toLocaleString('en-GB') },
                { key: 'results.cannibRate', label: 'Cannib.', i18nKey: 'col_cannib',
                  formatter: (v) => v + '%' },
                { key: 'results.conflictIndex', label: 'Conflict', i18nKey: 'col_conflict',
                  formatter: (v) => Math.round(v).toString() }
            ];
        }

        getPresets() { return null; }

        // -------------------------------------------------- briefing
        _updateBriefing(state) {
            const briefEl = document.getElementById('briefingText');
            if (!briefEl) return;
            const idx = Math.min(Math.max(((state && state.currentPeriod) || 1) - 1, 0), this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : (k) => k;
            briefEl.innerHTML = '<strong>' + t(round.titleKey) + '</strong><br>' + t(round.bodyKey);
        }

        // -------------------------------------------------- i18n
        getTranslations() {
            return {
                en: {
                    grade_ambidextrous: `Ambidextrous — both engines running`,
                    grade_building:     `Building — second model taking hold`,
                    grade_overreach:    `Overreach — growth broke the core`,
                    grade_fragile:      `Fragile — committed but unstable`,
                    grade_paralysis:    `Strategic paralysis — no second model`,
                    comp_heading:       `Brightwell — Board Verdict`,
                    comp_score_label:   `Ambidexterity score`,
                    comp_result_label:  `Underwriting result`,
                    comp_ratio_label:   `Worst combined ratio`,
                    comp_book_label:    `Direct-digital book`,
